def transform(value):
    if not isinstance(value,str): return {}
    out={}
    for line in value.splitlines():
        line=line.strip()
        if not line or line.startswith('#') or ':' not in line: continue
        k,v=line.split(':',1); k,v=k.strip(),v.strip()
        if k and v: out[k]=v
    return out
